// Shows what the thunks generated by `@_ExposeMainActorToCxx` and
// `@_ExposeMainActorMembersToCxx` look like.

// REQUIRES: swift_swift_parser
// REQUIRES: concurrency
// REQUIRES: swift_feature_GenerateBindingsForThrowingFunctionsInCXX

// RUN: %empty-directory(%t)
// RUN: split-file %s %t

// RUN: %target-swift-frontend %t/test.swift -module-name test -target %target-swift-5.1-abi-triple -parse-as-library -cxx-interoperability-mode=default -plugin-path %swift-plugin-dir -enable-experimental-feature GenerateBindingsForThrowingFunctionsInCXX -swift-version 6 -strict-memory-safety -emit-module -o %t -verify
// RUN: env SWIFT_BACKTRACE="" %target-swift-frontend %t/test.swift -module-name test -target %target-swift-5.1-abi-triple -parse-as-library -cxx-interoperability-mode=default -plugin-path %swift-plugin-dir -enable-experimental-feature GenerateBindingsForThrowingFunctionsInCXX -typecheck -dump-macro-expansions 2> %t/expansions.out
// RUN: %diff %t/expansions.out %t/expansions.expected

//--- test.swift
@_expose(Cxx)
public class NonSendable {}
public struct E: Error {}

/// A free function.
@_ExposeMainActorToCxx("renamed")
@MainActor public func freeFunction(_ x: Int, label y: inout NonSendable) -> Int { x }

@_expose(Cxx)
public struct Value {
  public var x = 0

  @_ExposeMainActorToCxx
  @MainActor public init?(x: Int) { self.x = x }

  @_ExposeMainActorToCxx
  @MainActor public func method<T>(_ t: T) -> T { t }

  @_ExposeMainActorToCxx
  @MainActor public mutating func mutatingMethod() { x += 1 }

  @_ExposeMainActorToCxx
  @MainActor public static func staticMethod() throws(E) -> Int { 0 }

  @_ExposeMainActorToCxx
  @MainActor public private(set) var property: Int {
    get { x }
    set { x = newValue }
  }

  @_ExposeMainActorToCxx
  @MainActor public subscript(i: Int) -> Int { x + i }
}

@_expose(Cxx)
@MainActor @_ExposeMainActorMembersToCxx
public final class Object {
  public init() {}
  public var object: NonSendable = NonSendable()
  // Skipped, as the thunk needs an explicit type.
  public var inferred = 0
  public func method() -> NonSendable { object }
  nonisolated public func nonisolatedMethod() {}
}

//--- expansions.expected
@__swiftmacro_4test12freeFunction21_ExposeMainActorToCxxfMp_.swift
------------------------------
/// A free function.
@available(swift, obsoleted: 1, message: "only available in C++")
@available(macOS 27, iOS 27, tvOS 27, watchOS 27, visionOS 27, *)
@_expose(Cxx, "renamed")
public nonisolated func _cxx_freeFunction(_ `x`: Int, `label` `y`: inout NonSendable) -> Int  {
    let _cxx_box0 = _CxxUncheckedSendable(Ref(`x`))
    var _cxx_box1 = _CxxUncheckedSendable(MutableRef(&`y`))
    return MainActor.assumeIsolated {
        _CxxUncheckedSendable(freeFunction(_cxx_box0.value.value, label: &_cxx_box1.value.value))
    } .take()
}
------------------------------
